// Obtener la URL desde el item actual del loop
const item = $input.first();
let url = item.json.Web || '';

// Verificar que la URL existe
if (!url || typeof url !== 'string' || url.trim() === '') {
  return [{ json: { error: 'URL no válida', original: url } }];
}

// Limpiar espacios en blanco
url = url.trim();

// Asegurar que tiene protocolo
if (!url.match(/^https?:\/\//i)) {
  url = 'https://' + url;
}

// Cambiar http:// a https://
url = url.replace(/^http:\/\//i, 'https://');

// Eliminar www. si existe
url = url.replace(/^(https:\/\/)www\./i, '$1');

// Asegurar que termine con /
if (!url.endsWith('/')) {
  url += '/';
}

// Retornar en formato correcto
return [{
  json: {
    cleanUrl: url,
    originalUrl: item.json.Web
  }
}];

// Obtener HTML de múltiples posibles ubicaciones
const input = $input.first().json;
let html = '';

// Prioridad: htmlContent del mapeo, o data legacy, o el JSON directo si es string
if (input.htmlContent && typeof input.htmlContent === 'string') {
  html = input.htmlContent;
} else if (input.data && typeof input.data === 'string') {
  html = input.data;
} else if (typeof input === 'string') {
  html = input;
}

// Si el HTML está vacío, devolver error informativo
if (!html || html.trim() === '' || html === '{}' || html === 'undefined') {
  return [{
    json: {
      cleanText: '',
      coloresPrincipales: [],
      colorPrimario: '#2563eb',
      colorSecundario: '#1e40af',
      colorAccento: '#3b82f6',
      error: 'No se pudo obtener el HTML de la web',
      correo: input.correo || '',
      web: input.web || ''
    }
  }];
}

// === LIMPIEZA DEL TEXTO VISIBLE ===
const cleanText = html
  .replace(/<script[\s\S]*?>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?>[\s\S]*?<\/style>/gi, '')
  .replace(/<\/?[^>]+(>|$)/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 4000);

// === EXTRACCIÓN DE COLORES ===
const coloresEncontrados = new Set();

// 1. Colores HEX (#fff, #ffffff)
const hexMatches = html.match(/#([0-9a-fA-F]{3}){1,2}\b/g) || [];
hexMatches.forEach(color => coloresEncontrados.add(color.toLowerCase()));

// 2. Colores RGB/RGBA
const rgbMatches = html.match(/rgba?\s*\(\s*\d{1,3}\s*,\s*\d{1,3}\s*,\s*\d{1,3}(?:\s*,\s*[\d.]+)?\s*\)/gi) || [];
rgbMatches.forEach(rgb => {
  const match = rgb.match(/(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})/);
  if (match) {
    const hex = '#' + [match[1], match[2], match[3]]
      .map(x => parseInt(x).toString(16).padStart(2, '0'))
      .join('');
    coloresEncontrados.add(hex.toLowerCase());
  }
});

// 3. Colores de CSS inline (style="...color:...")
const styleMatches = html.match(/(?:background-color|color|border-color)\s*:\s*([^;"']+)/gi) || [];
styleMatches.forEach(styleMatch => {
  const colorValue = styleMatch.split(':')[1]?.trim() || '';
  if (colorValue.startsWith('#')) {
    coloresEncontrados.add(colorValue.toLowerCase());
  } else if (colorValue.startsWith('rgb')) {
    const rgbMatch = colorValue.match(/(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})/);
    if (rgbMatch) {
      const hex = '#' + [rgbMatch[1], rgbMatch[2], rgbMatch[3]]
        .map(x => parseInt(x).toString(16).padStart(2, '0'))
        .join('');
      coloresEncontrados.add(hex.toLowerCase());
    }
  }
});

// Filtrar colores muy claros (blancos) y muy oscuros (negros)
const coloresUtiles = Array.from(coloresEncontrados).filter(color => {
  if (!color.startsWith('#') || color.length < 4) return false;
  let hex = color.slice(1);
  if (hex.length === 3) {
    hex = hex[0] + hex[0] + hex[1] + hex[1] + hex[2] + hex[2];
  }
  const r = parseInt(hex.slice(0, 2), 16);
  const g = parseInt(hex.slice(2, 4), 16);
  const b = parseInt(hex.slice(4, 6), 16);
  const brightness = (r * 299 + g * 587 + b * 114) / 1000;
  return brightness > 30 && brightness < 240;
});

// Seleccionar colores principales (máximo 5)
const coloresPrincipales = coloresUtiles.slice(0, 5);

// Asignar roles a los colores
const colorPrimario = coloresPrincipales[0] || '#2563eb';
const colorSecundario = coloresPrincipales[1] || '#1e40af';
const colorAccento = coloresPrincipales[2] || '#3b82f6';

return [{
  json: {
    cleanText: cleanText,
    coloresPrincipales: coloresPrincipales,
    colorPrimario: colorPrimario,
    colorSecundario: colorSecundario,
    colorAccento: colorAccento,
    correo: input.correo || '',
    web: input.web || ''
  }
}];

